def fizzbuzz(n):
    """Return a list of strings for the numbers 1..n."""
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result


print(fizzbuzz(15))

def letter_grade(score):
    """Return "A", "B", "C", "D" or "F" for a score 0-100."""
    if score >= 90:
        return "A"
    elif score >= 80:
        return "B"
    elif score >= 70:
        return "C"
    elif score >= 60:
        return "D"
    return "F"


def count_grades(scores):
    """Return a dict with counts for every letter."""
    counts = {"A": 0, "B": 0, "C": 0, "D": 0, "F": 0}
    for score in scores:
        counts[letter_grade(score)] += 1
    return counts


print(letter_grade(85))
print(count_grades([95, 82, 71, 64, 33, 88]))

