def clamp(value, low=0, high=10):
    """Push value back inside the window [low, high]."""
    if value < low:
        return low
    if value > high:
        return high
    return value


def average(values):
    """The mean of the clamped values."""
    total = 0
    for value in values:
        total += clamp(value)
    return total / len(values)


